from flask import Flask, request, send_file
import os

app = Flask(__name__)

@app.route('/img')
def img():
    file = request.args.get('file')
    if not file:
        return "Arquivo não especificado", 400

    file_path = os.path.join('uploads', file)  # Supondo que os arquivos estão na pasta 'uploads'

    if not os.path.exists(file_path):
        return "Arquivo não encontrado", 404

    # Determinar o tipo de conteúdo com base na extensão
    extension = file.lower().split('.')[-1]
    if extension in ['jpg', 'jpeg']:
        mimetype = 'image/jpeg'
    elif extension == 'png':
        mimetype = 'image/png'
    elif extension == 'gif':
        mimetype = 'image/gif'
    elif extension == 'webp':
        mimetype = 'image/webp'
    else:
        mimetype = 'application/octet-stream'

    return send_file(file_path, mimetype=mimetype)

if __name__ == '__main__':
    app.run(debug=True)

